import React from 'react';
import Marquee from "react-fast-marquee";
const data=[
    "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRuVMlGSI4dg5Zrxb7RQ8FxVmATXStjrJURhw&s",
    "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQoDqcjIsOWGj4Jub4lMo4UtdlOjih2ljnLHQ&s",
    "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSZRX7Yo1EHtsfy0BdWXvfaYZ-h1AmDAyIelg&s",
    "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSsCTwPfQcYX9OuuJrFrqeH9QL9H8AWawbBIA&s.png"
]

export default function IspImage(){
 return (
    <div>
    <center><h2>Service Providers</h2></center>
    <Marquee pauseOnHover={true}>
      {data.map((d,index)=>(
       <div key={index}>
        <img src={d} style={{objectFit:'contain',width:'200px',height:'160px'}}/>
       </div>
      )) 
      }
    </Marquee>
    </div>
 )
}